id #eaecf0;scroll-margin-top:90px}.page-head{display:flex;justify-content:space-between;border-bottom:1px solid #eaecf0;padding-bottom:12px;margin-bottom:25px;color:#98a2b3;font-size:9px}.page-content{font-size:13px;line-height:2.25;white-space:normal;word-break:break-word}.page-content mark.reader-highlight{background:#fff0a8;border-radius:3px;padding:1px 2px}.reader-lock{width:min(850px,100%);margin-top:-70px;position:relative;padding:38px 25px 30px;text-align:center;background:linear-gradient(to bottom,rgba(255,255,255,.94),#fff 35%);border:1px solid #eaecf0;border-radius:18px;box-shadow:0 -10px 30px rgba(16,24,40,.08)}.lock-icon{margin:auto;width:46px;height:46px;border-radius:13px;background:#eef2ff;display:grid;place-items:center}.lock-icon svg{width:22px;fill:none;stroke:currentColor;stroke-width:1.7;color:#4f46e5}.reader-lock h2{font-size:16px;margin:12px 0 6px}.reader-lock p{font-size:10px;color:#667085}.buy-btn{display:inline-flex;margin-top:12px;padding:11px 18px;border-radius:10px;background:#4f46e5;color:#fff;text-decoration:none;font-size:11px}.reader-empty{background:#fff;padding:60px;text-align:center;border-radius:16px}.reader-empty strong,.reader-empty span{display:block}.reader-empty span{font-size:10px;color:#98a2b3;margin-top:8px}@media(max-width:750px){.reader-top{padding:0 10px}.reader-title{display:none}.reader-main{display:block}.reader-sidebar{display:none}.reader-stage{padding:12px}.reader-page{padding:30px 20px;min-height:650px}.reader-tools .icon-btn:nth-of-type(1),.reader-tools .icon-btn:nth-of-type(2){display:none}}
