@push('scripts')<script>
(()=>{const shell=document.querySelector('.reader-shell'),pages=[...document.querySelectorAll('.reader-page')],list=[...document.querySelectorAll('.page-list button')],current=document.getElementById('currentPage'),zoomValue=document.getElementById('zoomValue');let zoom=1;const apply=()=>{document.querySelectorAll('.page-content').forEach(x=>x.style.fontSize=(13*zoom)+'px');zoomValue.textContent=Math.round(zoom*100)+'%'};document.querySelector('[data-action="zoom-in"]')?.addEventListener('click',()=>{zoom=Math.min(1.5,zoom+.1);apply()});document.querySelector('[data-action="zoom-out"]')?.addEventListener('click',()=>{zoom=Math.max(.8,zoom-.1);apply()});list.forEach(b=>b.onclick=()=>document.getElementById('page-'+b.dataset.page)?.scrollIntoView({behavior:'smooth',block:'start'}));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const n=e.target.dataset.page;current.textContent=n;list.forEach(b=>b.classList.toggle('active',b.dataset.page===n))}}),{threshold:.45});pages.forEach(p=>io.observe(p));document.querySelector('[data-action="highlight"]')?.addEventListener('click',()=>{const s=window.getSelection();if(!s||s.rangeCount===0||s.isCollapsed)return;const r=s.getRangeAt(0);const mark=document.createElement('mark');mark.className='reader-highlight';try{r.surroundContents(mark);localStorage.setItem('reader:'+shell.dataset.product,document.querySelector('.reader-pages').innerHTML)}catch(e){}});document.querySelector('[data-action="note"]')?.addEventListener('click',()=>{const text=prompt('یادداشت شما برای این بخش:');if(text){const key='reader-note:'+shell.dataset.product;const notes=JSON.parse(localStorage.getItem(key)||'[]');notes.push({page:current.textContent,text,at:Date.now()});localStorage.setItem(key,JSON.stringify(notes));alert('یادداشت ذخیره شد.')}});const saved=localStorage.getItem('reader:'+shell.dataset.product);if(saved&&shell.dataset.preview==='0'){document.querySelector('.reader-pages').innerHTML=saved}apply()})();
</script>@endpush
